const tabId = 118779795;

const contexts = await browserjs(tabId, async () => {
  const ids = [232556, 232515, 234754, 233106, 232702, 232677, 233107, 256349, 232572, 232697, 232734];
  const out = [];
  for (const id of ids) {
    const res = await fetch(`https://www.recreation.gov/api/camps/campgrounds/${id}`);
    const data = await res.json();
    const camp = data.campground;
    const text = JSON.stringify(camp);

    // Find all occurrences of horse (case-insensitive)
    const regex = /(.{0,100}horse.{0,100})/gi;
    let match;
    const matches = [];
    while ((match = regex.exec(text)) !== null) {
      matches.push(match[1]);
    }
    out.push({
      id,
      name: camp.facility_name,
      matches
    });
  }
  return out;
});

for (const c of contexts) {
  console.log(`=== ${c.name} (id: ${c.id}) ===`);
  for (const m of c.matches) {
    console.log(`  "...${m.replace(/\\"/g, '"')}..."`);
  }
}

