const tabId = 118779795;

const horseFacilities = await browserjs(tabId, async () => {
  // Fetch facilities within 100 miles
  const url = "https://www.recreation.gov/api/search?exact=false&lat=36.1627&lng=-86.7816&radius=100&size=100";
  const resp = await fetch(url);
  const data = await resp.json();

  const results = [];
  for (const item of data.results || []) {
    try {
      const campRes = await fetch(`https://www.recreation.gov/api/camps/campgrounds/${item.entity_id}`);
      if (!campRes.ok) continue;
      const campData = await campRes.json();
      const camp = campData.campground;
      const acts = (camp.facility_activity_codes || camp.activities?.map(a => a.activity_name) || []).map(a => typeof a === 'string' ? a : a.activity_name);

      const hasHorseActivity = acts.some(a => a.toLowerCase().includes("horse") || a.toLowerCase().includes("equestrian"));
      const text = JSON.stringify(camp).toLowerCase();
      const mentionsHorse = text.includes("horse") || text.includes("equestrian");

      if (hasHorseActivity || mentionsHorse) {
        results.push({
          id: item.entity_id,
          name: camp.facility_name,
          city: camp.facility_city,
          distance: item.distance,
          activities: acts,
          hasHorseActivity,
          mentionsHorse,
          campsiteTypes: camp.campsite_types
